using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckMinefield {
public sealed class MinefieldProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsMinefield")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.MinefieldProbe",false);UnityEditor.SessionState.SetBool("LWS.MinefieldProbe",false);
#endif
 if(run){var g=new GameObject("Minefield native acceptance");DontDestroyOnLoad(g);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<MinefieldProbe>();}}
 MinefieldMatch m;string folder,saved;bool had,restored;int errors,heat,launches,landings,replayHeat,recoveries;bool paused;readonly StringBuilder report=new StringBuilder();void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;}void Log(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+s);}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("MinefieldEvidence");yield return SportsProbeScene.Ensure<MinefieldMatch>("TruckMinefield");m=FindAnyObjectByType<MinefieldMatch>();if(m==null){Debug.LogError("Minefield probe requires its saved scene");yield break;}yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Log;Check(MinefieldRules.DrivenFinish(MineAttempt.Driving,1600,1610,out _)&&!MinefieldRules.DrivenFinish(MineAttempt.Launched,1600,1610,out _),"driven and mine-launched finish eligibility differ");Check(MinefieldRules.Leaders(new[]{1234,1234,-1},7)==3,"displayed-precision heat ties share points");Check(MinefieldRules.Leaders(new[]{-1,-1},3)==0,"incomplete attempts cannot receive invented scores");for(int i=0;i<8;i++){m.setup.players[i].source=BowlingSource.AI;m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);}Check(m.StartMatch(),"eight-AI physical match starts");Time.timeScale=4;float end=Time.realtimeSinceStartup+1000,next=0;while(!m.Finished&&Time.realtimeSinceStartup<end){if(m.Heat!=heat){heat=m.Heat;report.AppendLine("HEAT "+heat+" weather="+m.weatherField.Description);}
 foreach(var r in m.racers){if(r.LandingLocks>1)Check(false,"one final-rest lock per attempt invariant");}if(!paused&&m.Phase==MinefieldPhase.Driving&&Array.Exists(m.racers,r=>r.Phase==MineAttempt.Launched)){paused=true;m.Pause();var p=m.racers[0].truck.body.position;float clock=m.HeatTime;yield return new WaitForSecondsRealtime(.2f);Check(m.Paused&&p==m.racers[0].truck.body.position&&clock==m.HeatTime,"pause freezes flight and authoritative heat clock");m.Resume();Time.timeScale=4;}
 if(m.Phase==MinefieldPhase.Replay&&replayHeat!=m.Heat){replayHeat=m.Heat;for(int i=0;i<8;i++){launches+=m.racers[i].Launches;landings+=m.racers[i].LandingLocks;if(m.racers[i].RecoveryLocked)recoveries++;}report.AppendLine("RESOLVED heat="+m.Heat+" time="+m.HeatTime+" history="+m.HistoricalFlags.Count+" recoveries="+recoveries);{int locked=m.HeatLocks;m.ExtraAction("replayangle");m.ExtraAction("replayspeed");Check(m.replay.Playing&&m.HeatLocks==locked,"recorded replay cannot finalize another heat");}}
 if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",report+"CURRENT heat="+m.Heat+" phase="+m.Phase+" time="+m.HeatTime+" points="+string.Join(",",m.points)+" attempts="+string.Join(",",Array.ConvertAll(m.racers,r=>r.Phase+":"+r.Distance))+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}
 Check(m.Finished&&m.Winner>=0,"complete eight-AI physical match");Check(launches>0&&landings>0,"actual blasts and supported final rests occurred");Check(paused,"flight pause fixture executed");Check(recoveries==0,"ordinary full match does not rely on pathological90s recovery locks");report.AppendLine("MATCH heats="+m.Heat+" winner="+m.Winner+" points="+string.Join(",",m.points)+" launches="+launches+" rests="+landings+" recoveryLocks="+recoveries+" ERRORS="+errors+"; AI controls and actual PhysX, no hardware/human acceptance");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("MINEFIELD_PROBE_COMPLETE "+report);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Log;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
}
